// HasTask applies the HasEdge predicate on the "task" edge.
func HasTask() predicate.GenerationImage {
	return predicate.GenerationImage(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, TaskTable, TaskColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasTaskWith applies the HasEdge predicate on the "task" edge with a given conditions (other predicates).
func HasTaskWith(preds ...predicate.GenerationTask) predicate.GenerationImage {
	return predicate.GenerationImage(func(s *sql.Selector) {
		step := newTaskStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.GenerationImage) predicate.GenerationImage {
	return predicate.GenerationImage(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.GenerationImage) predicate.GenerationImage {
	return predicate.GenerationImage(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.GenerationImage) predicate.GenerationImage {
	return predicate.GenerationImage(sql.NotPredicates(p))
}
